174	+import { z } from "zod";
175	+import { SPAWN_PROTECTION_SECONDS } from "../encounters/rules.js";
176	+import { formatIssues, privateMatch, rulesPresets, type ValidationResult } from "../rules.js";
177	+import { WORLD_STEPS_PER_SECOND } from "../sailing.js";
178	+
179	+/** §2: the ready check lasts 20 seconds while clients preload arenas. */
180	+export const READY_COUNTDOWN_SECONDS = 20;
181	+/** §2: departure is the 45 seconds of spawn protection from control start; the encounter rules grant the protection. */
182	+export const DEPARTURE_SECONDS = SPAWN_PROTECTION_SECONDS;
183	+/** §2: private tests may start with two to eight players. */
184	+export const PRIVATE_MIN_PLAYERS = 2;
185	+/** §2: public matches do not start short-handed; they need every seat of the eight-player preset. */
186	+export const PUBLIC_SEATS = rulesPresets.alpha.maxPlayers;
187	+
188	+/** The match flow rules (§2) in world ticks (20 a second) and seats. */
189	+export const matchRulesSchema = z
190	+  .strictObject({
191	+    /** World ticks from the ready check to control start. */
192	+    readyTicks: z.int().positive(),
193	+    /** World ticks from control start to exploration: a HUD label, the protection itself is the encounter rules'. */
194	+    departureTicks: z.int().positive(),
195	+    /** Players a public match needs before its ready check. */
196	+    publicSeats: z.int().min(2).max(8),
197	+    /** The fewest players a private match starts with. */
198	+    privateMinPlayers: z.int().min(2).max(8),
199	+    /** The most players a private match admits. */
200	+    privateMaxPlayers: z.int().min(2).max(8),
201	+  })
202	+  .superRefine((rules, ctx) => {
203	+    if (rules.privateMinPlayers > rules.privateMaxPlayers) {
204	+      ctx.addIssue({
205	+        code: "custom",
206	+        path: ["privateMinPlayers"],
207	+        message: `a private minimum of ${rules.privateMinPlayers} players exceeds the maximum of ${rules.privateMaxPlayers}`,
208	+      });
209	+    }
210	+  });
211	+
212	+export type MatchRules = z.infer<typeof matchRulesSchema>;
213	+
214	+export const matchRules: MatchRules = {
215	+  readyTicks: READY_COUNTDOWN_SECONDS * WORLD_STEPS_PER_SECOND,
216	+  departureTicks: DEPARTURE_SECONDS * WORLD_STEPS_PER_SECOND,
217	+  publicSeats: PUBLIC_SEATS,
218	+  privateMinPlayers: PRIVATE_MIN_PLAYERS,
219	+  privateMaxPlayers: privateMatch.maxPlayers,
220	+};
221	+
222	+export function validateMatchRules(candidate: unknown): ValidationResult<MatchRules> {
223	+  const parsed = matchRulesSchema.safeParse(candidate);
224	+  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
225	+}
