390	+    expect(script.last.filter((event) => event.kind === "join-refused")).toEqual([{ kind: "join-refused", tick: 1, playerId: "p9", reason: "full" }]);
391	+    expect(script.state.players).toHaveLength(8);
392	+    const full = new Script(PUBLIC).at(1, ...join(...EIGHT, "p9"));
393	+    expect(full.last.filter((event) => event.kind === "join-refused")).toHaveLength(1);
394	+    expect(full.state.phase).toBe("ready");
