762	+    leavePerMille: [20, 60, 150, 300][index % 4]!,
763	+    // A third of the scenarios never claim or fault, so they run to the deadline or empty out.
764	+    claimPerMille: index % 3 === 0 ? 0 : 2 + draw(6),
765	+    faultPerMille: index % 3 === 0 ? 0 : draw(3),
766	+    skipPerMille: [0, 100, 400][index % 3]!,
767	+  };
768	+});
769	+
770	+const EXERCISED = new Set<string>();
771	+const MUST_EXERCISE = [
772	+  ...MATCH_PHASES.map((phase) => `phase:${phase}`),
773	+  ...MATCH_END_REASONS.map((reason) => `end:${reason}`),
774	+  "ready->lobby",
775	+  "join-refused:started",
776	+  "join-refused:full",
777	+  "start-refused:public",
778	+  "start-refused:not-host",
779	+  "start-refused:too-few",
780	+  "transition-skipped",
781	+  "stale-input",
782	+  "left-in-results",
783	+];
784	+
785	+const RANK = new Map<string, number>(MATCH_PHASES.map((phase, index) => [phase, index]));
786	+
787	+interface Tally {
788	+  collected: number;
789	+  thefts: number;
790	+  lost: number;
791	+  duelsWon: number;
792	+  duelsLost: number;
793	+  duelsDrawn: number;
794	+  gold: number | null;
795	+  cachesClaimed: number;
796	+  islands: Set<string>;
797	+}
798	+
799	+/** Plays one seeded match the way a room would: it reads the state to choose each tick's reports. */
800	+function play(config: MatchConfig, scenario: Scenario): { inputs: MatchInput[]; events: MatchEvent[]; state: MatchState } {
801	+  const draw = generator(scenario.seed);
802	+  const chance = (perMille: number) => draw(1000) < perMille;
803	+  let state = deepFreeze(createMatchState(config));
804	+  const inputs: MatchInput[] = [];
805	+  const events: MatchEvent[] = [];
806	+  let tick = 0;
807	+  let resultsSeen = 0;
808	+
809	+  for (let step = 0; step < MAX_STEPS && state.end === null; step++) {
810	+    const before = state;
811	+    tick += 1 + (chance(scenario.skipPerMille) ? draw(60) : 0);
812	+    const controlStart = state.controlStartTick ?? (state.readyTick !== null ? state.readyTick + config.readyTicks : null);
813	+    const deadline = controlStart === null ? null : controlStart + config.durationTicks;
814	+    // A room steps every tick near the deadline, so the claim module's deadline report lands on its own tick.
815	+    if (deadline !== null && tick > deadline) tick = deadline;
816	+    if (tick <= state.tick) tick = state.tick + 1;
817	+    const running = state.controlStartTick !== null || (controlStart !== null && tick >= controlStart);
818	+    const inPlayers = state.controlStartTick !== null ? state.players.map((player) => player.id) : [];
819	+    const pick = <T,>(list: readonly T[]) => list[draw(list.length)]!;
820	+
821	+    const reports: MatchReport[] = [];
822	+    const slots = draw(5);
823	+    for (let slot = 0; slot < slots; slot++) {
824	+      const roll = draw(1000);
825	+      if (roll < 250) reports.push({ kind: "join", playerId: pick(IDS) });
826	+      else if (roll < 250 + scenario.leavePerMille) reports.push({ kind: "leave", playerId: pick(IDS) });
827	+      else if (roll < 400 + scenario.leavePerMille) {
828	+        const host = state.host;
829	+        reports.push({ kind: "start", playerId: host !== null && chance(700) ? host : pick(IDS) });
830	+      } else if (inPlayers.length >= 2 && roll < 500 + scenario.leavePerMille) {
831	+        const a = pick(inPlayers);
832	+        const others = inPlayers.filter((id) => id !== a);
833	+        const b = pick(others);
834	+        const outcome = draw(3);
835	+        reports.push({ kind: "duel-ended", playerIds: [a, b], winner: outcome === 0 ? null : outcome === 1 ? a : b });
836	+      } else if (inPlayers.length > 0) {
837	+        const playerId = pick(inPlayers);
838	+        switch (draw(6)) {
839	+          case 0:
840	+            reports.push({ kind: "collected", playerId });
841	+            break;
842	+          case 1:
843	+            reports.push({ kind: "stole", playerId });
844	+            break;
845	+          case 2:
846	+            reports.push({ kind: "lost", playerId });
847	+            break;
848	+          case 3:
849	+            reports.push({ kind: "cache-claimed", playerId });
850	+            break;
851	+          case 4:
852	+            reports.push({ kind: "island-visited", playerId, island: pick(ISLANDS) });
853	+            break;
854	+          default:
855	+            reports.push({ kind: "gold", playerId, gold: draw(200) });
856	+        }
857	+      }
858	+    }
859	+    if (running && inPlayers.length > 0 && chance(scenario.claimPerMille)) reports.push({ kind: "match-ended", tick, reason: "claim", winner: pick(inPlayers) });
860	+    if (chance(scenario.faultPerMille)) reports.push({ kind: "fault" });
861	+    if (deadline !== null && tick === deadline) {
862	+      // The claim module ends on its deadline tick unless a claim completed on it.
863	+      if (!reports.some((report) => report.kind === "match-ended")) reports.push({ kind: "match-ended", tick, reason: "deadline", winner: null });
864	+    }
865	+
866	+    const input = deepFreeze({ tick, reports });
867	+    const stepped = stepMatch(config, before, input);
868	+    inputs.push(input);
869	+    events.push(...stepped.events);
870	+    state = deepFreeze(stepped.state);
871	+
872	+    // Invariants of one step.
873	+    let phase = before.phase;
874	+    for (const event of stepped.events) {
875	+      if (event.kind === "phase-changed") {
876	+        expect(event.from).toBe(phase);
877	+        const backwards = RANK.get(event.to)! <= RANK.get(event.from)!;
878	+        if (backwards) {
879	+          expect([event.from, event.to]).toEqual(["ready", "lobby"]);
880	+          EXERCISED.add("ready->lobby");
881	+        }
882	+        phase = event.to;
883	+        if (event.tick < tick) EXERCISED.add("transition-skipped");
884	+      }
885	+      if (event.kind === "control-started") {
886	+        expect(before.readyTick).not.toBeNull();
887	+        expect(event.tick).toBe(before.readyTick! + config.readyTicks);
888	+      }
889	+      if (event.kind === "join-refused") EXERCISED.add(`join-refused:${event.reason}`);
890	+      if (event.kind === "start-refused") EXERCISED.add(`start-refused:${event.reason}`);
891	+      if (event.kind === "match-ended") {
892	+        resultsSeen++;
893	+        expect(event.results).toBe(state.results);
894	+      }
895	+    }
896	+    expect(phase).toBe(state.phase);
897	+    EXERCISED.add(`phase:${state.phase}`);
898	+    expect(state.tick).toBe(tick);
899	+    expect(state.end === null).toBe(state.results === null);
900	+    expect(state.end === null).toBe(state.phase !== "ended");
901	+    const present = state.players.filter((player) => !player.left);
902	+    expect(present.length).toBeLessThanOrEqual(config.seats);
903	+    if (state.phase === "ready") expect(present.length).toBeGreaterThanOrEqual(config.minPlayers);
904	+    if (state.phase === "lobby" || state.phase === "ready") expect(state.players.every((player) => !player.left)).toBe(true);
905	+    if (!config.custom) expect(state.host).toBeNull();
906	+    else if (state.end === null) expect(state.host).toBe(present.length === 0 ? null : [...present].sort((a, b) => a.order - b.order)[0]!.id);
907	+    if (state.phase === "exploration") expect(tick).toBeGreaterThanOrEqual(state.controlStartTick! + config.departureTicks);
908	+    if (state.phase === "departure") expect(tick).toBeLessThan(state.controlStartTick! + config.departureTicks);
909	+    for (const probe of [tick - 100, tick, tick + 100]) {
910	+      const [spent, left] = [elapsed(state, probe), remaining(state, probe)];
911	+      expect(spent).toBeGreaterThanOrEqual(0);
912	+      expect(left).toBeGreaterThanOrEqual(0);
913	+      if (spent <= config.durationTicks) expect(spent + left).toBe(config.durationTicks);
914	+    }
915	+    hashState(state);
916	+
917	+    // A repeated or stale input changes nothing.
918	+    if (step % 17 === 0) {
919	+      const again = stepMatch(config, state, input);
920	+      expect(again.state).toBe(state);
921	+      expect(again.events).toEqual([]);
922	+      EXERCISED.add("stale-input");
923	+    }
924	+  }
925	+  expect(resultsSeen).toBe(state.end === null ? 0 : 1);
926	+  return { inputs, events, state };
927	+}
928	+
929	+/** Counts every accomplishment report from control start to the end, independently of the step. */
930	+function tally(inputs: readonly MatchInput[], state: MatchState): Map<string, Tally> {
931	+  const tallies = new Map<string, Tally>();
932	+  const of = (id: string) => {
933	+    let entry = tallies.get(id);
934	+    if (entry === undefined) {
935	+      entry = { collected: 0, thefts: 0, lost: 0, duelsWon: 0, duelsLost: 0, duelsDrawn: 0, gold: null, cachesClaimed: 0, islands: new Set() };
936	+      tallies.set(id, entry);
937	+    }
938	+    return entry;
939	+  };
940	+  if (state.controlStartTick === null) return tallies;
941	+  for (const input of inputs) {
942	+    if (input.tick < state.controlStartTick || (state.end !== null && input.tick > state.end.tick)) continue;
943	+    for (const report of input.reports) {
944	+      switch (report.kind) {
945	+        case "collected":
946	+          of(report.playerId).collected++;
947	+          break;
948	+        case "stole":
949	+          of(report.playerId).thefts++;
950	+          break;
951	+        case "lost":
952	+          of(report.playerId).lost++;
953	+          break;
954	+        case "cache-claimed":
955	+          of(report.playerId).cachesClaimed++;
956	+          break;
957	+        case "island-visited":
958	+          of(report.playerId).islands.add(report.island);
959	+          break;
960	+        case "gold":
961	+          of(report.playerId).gold = report.gold;
962	+          break;
963	+        case "duel-ended":
964	+          for (const id of report.playerIds) {
965	+            if (report.winner === null) of(id).duelsDrawn++;
966	+            else if (report.winner === id) of(id).duelsWon++;
967	+            else of(id).duelsLost++;
968	+          }
969	+          break;
970	+        default:
971	+          break;
972	+      }
973	+    }
974	+  }
975	+  return tallies;
976	+}
977	+
978	+describe("match flow properties", () => {
979	+  afterAll(() => {
980	+    expect(MUST_EXERCISE.filter((label) => !EXERCISED.has(label))).toEqual([]);
981	+  });
982	+
983	+  for (const scenario of SCENARIOS) {
984	+    it(`keeps its invariants: seed ${scenario.seed}, ${scenario.kind}, leaves ${scenario.leavePerMille}‰, skips ${scenario.skipPerMille}‰`, () => {
985	+      const config = createMatchConfig({ kind: scenario.kind, ...QUICK });
986	+      const { inputs, events, state } = play(config, scenario);
987	+
988	+      // Replaying the same inputs gives the same state, events and hash; so does replaying them with repeats.
989	+      const first = replayMatch(config, createMatchState(config), inputs);
990	+      expect(first.hash).toBe(hashState(state));
991	+      expect(first.events).toEqual(events);
992	+      const repeated = inputs.flatMap((input, index) => (index % 3 === 0 ? [input, input] : [input]));
993	+      expect(replayMatch(config, createMatchState(config), repeated).hash).toBe(first.hash);
994	+
995	+      expect(events.filter((event) => event.kind === "control-started").length).toBe(state.controlStartTick === null ? 0 : 1);
996	+      expect(events.filter((event) => event.kind === "match-ended").length).toBeLessThanOrEqual(1);
997	+
998	+      if (state.end === null) return;
999	+      EXERCISED.add(`end:${state.end.reason}`);
1000	+      const results = state.results!;
1001	+      expect(results.winner === null).toBe(state.end.reason !== "claim");
1002	+      expect(results.players.map((player) => player.id).sort()).toEqual(state.players.map((player) => player.id).sort());
1003	+      expect(results.players.filter((player) => player.winner).map((player) => player.id)).toEqual(results.winner === null ? [] : [results.winner]);
1004	+      for (let index = 1; index < results.players.length; index++) {
1005	+        const a = results.players[index - 1]!;
1006	+        const b = results.players[index]!;
1007	+        const ordered = Number(a.winner) > Number(b.winner) || (a.winner === b.winner && (a.rubbingsHeld > b.rubbingsHeld || (a.rubbingsHeld === b.rubbingsHeld && a.id < b.id)));
1008	+        expect(ordered).toBe(true);
1009	+      }
1010	+      const tallies = tally(inputs, state);
1011	+      for (const line of results.players) {
1012	+        const expected = tallies.get(line.id);
1013	+        const player = state.players.find((candidate) => candidate.id === line.id)!;
1014	+        expect(line.left).toBe(player.left);
